"""Verify calibration choices and paired accuracy from the digit-write records."""

import hashlib
import itertools
import json
import math
import statistics
import sys
from pathlib import Path

from ladder_audit import last_box


def read(path):
    return json.loads(path.read_bytes())


def hash_file(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def summaries(rows, names):
    result = {}
    for name in names:
        values = [row[name] for row in rows]
        result[name] = {"prefixes": len(rows), "mean_kl": statistics.mean(v["kl"] for v in values),
                        "mean_js": statistics.mean(v["js"] for v in values),
                        "mean_tv": statistics.mean(v["tv"] for v in values),
                        "moved": sum(v["moved"] for v in values)}
    return result


def valid(row, low, high):
    return low <= row["mean_kl"] <= high and row["mean_js"] <= 0.0005


def calibration(work):
    record = read(work / "calibration.json")
    directions = read(work / "directions.json")
    assert record["construction_sha256"] == hash_file(work / "directions.json")
    assert record["panel_sha256"] == hash_file(work / "panels.json")
    assert record["directions_sha256"] == directions["directions_sha256"]
    assert record["incumbent_equals_reward"] == directions["bitwise_deployed_directions"]
    names = ["reward", "prior", "reversed"]
    if not record["incumbent_equals_reward"]:
        names.append("incumbent")
    recomputed_scales = {name: [2 ** (power / 4) for power in range(-24, -7)] for name in names}
    assert recomputed_scales == record["candidates"]
    labels = [f"{name}/{i}" for name, values in recomputed_scales.items() for i in range(len(values))]
    candidates = summaries(record["candidate_measurements"], labels)
    assert candidates == record["candidate_summary"]
    chosen, matched = {}, {}
    for name, values in recomputed_scales.items():
        options = []
        for i, value in enumerate(values):
            row = candidates[f"{name}/{i}"]
            if valid(row, 0.00035, 0.00065):
                options.append((abs(math.log(row["mean_kl"] / 0.0005)), value, i))
        if options:
            _, chosen[name], index = min(options)
            matched[name] = candidates[f"{name}/{index}"]
    assert chosen == record["chosen"] and matched == record["chosen_summary"]
    ranks = [v["mean_kl"] for v in matched.values()]
    passed = set(chosen) == set(names) and max(ranks) <= 1.55 * min(ranks)
    verification = {}
    if passed:
        verification = summaries(record["verification"]["measurements"], names)
        ranks = [v["mean_kl"] for v in verification.values()]
        passed = all(valid(v, 0.00020, 0.0010) for v in verification.values()) and max(ranks) <= 1.8 * min(ranks)
    else:
        assert record["verification"] is None
    assert verification == record["verification_summary"] and record["qualified"] == passed
    return {"qualified": passed, "matching": matched, "verification": verification,
            "chosen": chosen, "calibration_sha256": hash_file(work / "calibration.json")}


def arm_audit(panel, raw, seed, scope):
    seen, lengths, correct, parseable, caps = [], [], 0, 0, 0
    for index, (spec, row) in enumerate(zip(panel, raw["observations"], strict=True)):
        assert spec["id"] == row["id"] and spec["gold"] == row["gold"] and row["family"] == "packing"
        batch_start = (index // 8) * 8
        salt = f"qwen.digit-low.{scope}.L1.{batch_start}".encode()
        expected_seed = (seed ^ int.from_bytes(hashlib.blake2b(salt, digest_size=8).digest(), "little")) % (2**63)
        assert row["batch_seed"] == expected_seed
        answers = []
        for text, tokens, length in zip(row["text"], row["tokens"], row["lengths"], strict=True):
            assert 0 <= length <= 512 and len(tokens) == row["prompt_length"] + length
            answers.append(last_box(text))
        assert len(answers) == 4 and answers == row["answers"]
        outcomes = [int(answer == spec["gold"]) for answer in answers]
        assert outcomes == row["rewards"]
        seen.append(sum(outcomes))
        correct += sum(outcomes)
        parseable += sum(value is not None for value in answers)
        caps += row["lengths"].count(512)
        lengths.extend(row["lengths"])
    return seen, {"draws": len(lengths), "correct": correct, "parseable": parseable, "capped": caps,
                  "mixed": sum(0 < value < 4 for value in seen), "median_tokens": statistics.median(lengths)}


def contrast(primary, control):
    stem = [left - right for left, right in zip(primary, control, strict=True)]
    pairs = [left + right for left, right in zip(stem[::2], stem[1::2], strict=True)]
    nonzero = [value for value in pairs if value]
    observed = sum(pairs)
    possibilities = 2**len(nonzero)
    tail = sum(sum(sign * delta for sign, delta in zip(signs, nonzero, strict=True)) >= observed
               for signs in itertools.product((-1, 1), repeat=len(nonzero)))
    return {"pair_deltas": pairs, "gain": observed, "tail": tail, "denominator": possibilities, "p": tail / possibilities,
            "passed": observed >= 8 and tail * 40 <= possibilities}


def transfer(work, files):
    drift = calibration(work)
    assert drift["qualified"]
    panels = read(work / "panels.json")["panels"]
    seen, scores, raw_arms = {}, {}, {}
    for path in files:
        trial = read(work / path)
        assert trial["panel_sha256"] == hash_file(work / "panels.json")
        assert trial["calibration_sha256"] == drift["calibration_sha256"]
        assert trial["construction_sha256"] == hash_file(work / "directions.json")
        for name, raw in trial["arms"].items():
            if name in raw_arms:
                assert name == "zero" and raw_arms[name] == raw
                continue
            raw_arms[name] = raw
            assert (raw["transfer"]["deployed_sha256"] is None) == (name == "zero")
            assert raw["transfer"]["deployed_sha256"] == raw["adaptation"]["deployed_sha256"]
            seen[name], primary = arm_audit(panels["transfer"], raw["transfer"], 811082, "transfer")
            _, adaptation = arm_audit(panels["adaptation"], raw["adaptation"], 811081, "adaptation")
            scores[name] = {"transfer": primary, "adaptation": adaptation,
                            "deployed_sha256": raw["transfer"]["deployed_sha256"]}
    baseline = scores["zero"]["transfer"]
    baseline_passed = baseline["parseable"] >= 96 and baseline["mixed"] >= 8
    if baseline_passed:
        assert set(seen) == {"zero", *drift["chosen"]}
        assert sum("zero" in read(work / path)["arms"] for path in files) == 2
    else:
        assert set(seen) == {"zero"}
    contrasts, harm = {}, {}
    if baseline_passed:
        contrasts = {name: contrast(seen["reward"], seen[name]) for name in seen if name != "reward"}
        primary = scores["reward"]["transfer"]
        harm = {"cap_increase": primary["capped"] - baseline["capped"],
                "parseable_loss": baseline["parseable"] - primary["parseable"]}
    passed = (baseline_passed and contrasts["zero"]["passed"] and contrasts["prior"]["passed"]
              and harm["cap_increase"] <= 4 and harm["parseable_loss"] <= 4)
    return {"passed": passed, "baseline_passed": baseline_passed, "scores": scores,
            "contrasts": contrasts, "harm": harm, "calibration": drift}


if __name__ == "__main__":
    if not __debug__:
        raise RuntimeError("The write audit requires assertions.")
    phase, directory, *files = sys.argv[1:]
    work = Path(directory)
    assert phase in ("calibration", "transfer")
    result = calibration(work) if phase == "calibration" else transfer(work, files)
    with (work / f"{phase}_audit.json").open("x", encoding="utf-8") as stream:
        json.dump(result, stream, sort_keys=True, indent=2, allow_nan=False)
        stream.write("\n")

